/// <summary>
/// Post production finish jounrals on robot interface import
/// </summary>
public class AVARUMProdImportFinishManager extends RunBaseBatch
{

}

Method.Source:
/// <summary>
/// Post a production finish report
/// </summary>
/// <param name = "_AVARUMProdImportFinishTable">Request table</param>
/// <returns>true if successull</returns>
static public boolean postFinish(AVARUMProdImportFinishTable _AVARUMProdImportFinishTable)
{
    ProdUpdReportFinished   prodUpdReportFinished = new ProdUpdReportFinished();
    ProdTable               prodTable=prodTable::find(_AVARUMProdImportFinishTable.ProdId);
    boolean                 ret=true; 
    AVARUMProdImportFinishTable locAVARUMProdImportFinishTable;

    try
    {
        ttsbegin;
        ProdParmReportFinished prodParmReportFinished;
        prodParmReportFinished.initParmDefault();
        prodParmReportFinished.initFromProdTable(prodTable);
        if (_AVARUMProdImportFinishTable.LicensePlateId)
        {
            InventDim locInventDim=InventDim::find(prodParmReportFinished.InventDimId);
            locInventDim.LicensePlateId=_AVARUMProdImportFinishTable.LicensePlateId;
            prodParmReportFinished.InventDimId = InventDim::findOrCreate(locInventDim).inventDimId;
        }            
        prodParmReportFinished.ParmId = NumberSeq::newGetNum(CompanyInfo::numRefParmId()).num();
        prodParmReportFinished.QtyGood = _AVARUMProdImportFinishTable.QtyKg;
        prodParmReportFinished.bomAutoConsump = BOMAutoConsump::FlushingPrincip;
        prodParmReportFinished.AcceptError = true;
        prodParmReportFinished.EndJob = _AVARUMProdImportFinishTable.EndJob;
        prodParmReportFinished.EndPicklist          = NoYes::No;
        prodParmReportFinished.EndRouteCard         = NoYes::No;
        prodParmReportFinished.JournalShowInfo      = NoYes::No;
        prodParmReportFinished.PostNow              = NoYes::Yes;
        prodParmReportFinished.ReportFinishProd     = NoYes::Yes;
        prodParmReportFinished.insert();

        prodUpdReportFinished.parmParmBuffer(prodParmReportFinished);
        prodUpdReportFinished.initProdTable();
        prodUpdReportFinished.run();
        ttscommit;
    }
    catch
    {
        ret=false;
    }
    ttsbegin;
    update_recordset locAVARUMProdImportFinishTable
        setting JobStatus=(ret ? ParmJobStatus::Executed : ParmJobStatus::ContainErrors)
        where locAVARUMProdImportFinishTable.RecId==_AVARUMProdImportFinishTable.recid;
    ttscommit;

    return ret;
}

private AVARUMProdImportFinishTable getNext()
{
    AVARUMProdImportFinishTable locAVARUMProdImportFinishTable;
    select firstonly locAVARUMProdImportFinishTable
        where locAVARUMProdImportFinishTable.JobStatus==ParmJobStatus::Waiting;

    return locAVARUMProdImportFinishTable;
}

public void run()
{
    AVARUMProdImportFinishTable locAVARUMProdImportFinishTable;

    do
    {
        locAVARUMProdImportFinishTable=this.getNext();
        if (locAVARUMProdImportFinishTable)
        {
            AVARUMProdImportFinishManager::postFinish(locAVARUMProdImportFinishTable);
        }

    }
    while (locAVARUMProdImportFinishTable);
}

/// <summary>
/// Job description
/// </summary>
/// <returns>Description</returns>
static ClassDescription description()
{
    return "@AVARUM:AVARUMProdImportFinishManagerLbl";
}

static public void main(Args _args)
{
    AVARUMProdImportFinishManager AVARUMProdImportFinishManager=new AVARUMProdImportFinishManager();

    if (AVARUMProdImportFinishManager.prompt())
    {
        AVARUMProdImportFinishManager.runOperation();
    }

    // TST
    // AVARUMProdImportFinishService::construct().finishProduction('RU5CHARGE000000009', 0, 1, systemDateGet(), 'exbjtst2', false);
}
